.s { box-sizing: border-box; min-height: 340px; padding: 28px; font: 15px/1.5 "Helvetica Neue", Helvetica, Arial, sans-serif; position: relative; overflow: hidden; }
.s *, .s *::before, .s *::after { box-sizing: border-box; }
